# add-duo-test-targets.rb - add the DuoUITests and DuoPerfTests UI test targets
# to an Xcode project without opening Xcode, using the xcodeproj gem that ships
# with CocoaPods. Copies templates/DuoUITests.swift and templates/DuoPerfTests.swift
# next to the project, adds both targets to the scheme's Test action and sets
# that action to Release (a Debug React Native / Expo host app loads its
# JavaScript from Metro, which nothing in the pipeline starts).
#
# Expo projects: ios/ is regenerated by `expo prebuild`, so rerun this after
# every `build.sh --prebuild`. Verified 28 Oct 2026 on an Expo SDK 54 app with
# xcodeproj 1.28.1 (Homebrew CocoaPods 1.17).
#
# Usage, from the app root (the directory that holds duo.yaml):
#   ruby "$DUO/templates/add-duo-test-targets.rb" <path/to/App.xcodeproj> <app target> "$DUO/templates" [deployment target]
# With Homebrew CocoaPods, use its Ruby and gems:
#   GEM_HOME=/opt/homebrew/Cellar/cocoapods/<ver>/libexec /opt/homebrew/opt/ruby/bin/ruby "$DUO/templates/add-duo-test-targets.rb" ...
# Then build for testing once:
#   xcodebuild build-for-testing -workspace ios/App.xcworkspace -scheme App -configuration Release \
#     -sdk iphonesimulator -destination 'generic/platform=iOS Simulator' -derivedDataPath <build.json derived_data>
require 'fileutils'
require 'xcodeproj'

project_path, app_name, templates, deployment_arg = ARGV
abort 'usage: add-duo-test-targets.rb <App.xcodeproj> <app target name> <duo-ready templates dir> [deployment target]' unless project_path && app_name && templates

project = Xcodeproj::Project.open(project_path)
app = project.native_targets.find { |t| t.name == app_name } or abort "target #{app_name} not found in #{project_path}"
app_settings = app.build_configurations.first.build_settings
deployment = deployment_arg || app_settings['IPHONEOS_DEPLOYMENT_TARGET'] || '15.1'
bundle_prefix = app_settings['PRODUCT_BUNDLE_IDENTIFIER'] || "com.example.#{app_name.downcase}"
project_dir = File.dirname(project_path)

added = []
%w[DuoUITests DuoPerfTests].each do |name|
  if project.native_targets.any? { |t| t.name == name }
    puts "#{name}: already present"
    next
  end
  dir = File.join(project_dir, name)
  FileUtils.mkdir_p(dir)
  FileUtils.cp(File.join(templates, "#{name}.swift"), File.join(dir, "#{name}.swift"))

  target = project.new_target(:ui_test_bundle, name, :ios, deployment)
  group = project.main_group.find_subpath(name, true)
  group.set_source_tree('<group>')
  group.set_path(name)
  file = group.new_reference("#{name}.swift")
  target.add_file_references([file])
  target.add_dependency(app)
  target.build_configurations.each do |config|
    s = config.build_settings
    s['TEST_TARGET_NAME'] = app_name
    s['PRODUCT_BUNDLE_IDENTIFIER'] = "#{bundle_prefix}.#{name}"
    s['PRODUCT_NAME'] = '$(TARGET_NAME)'
    s['GENERATE_INFOPLIST_FILE'] = 'YES'
    s['SWIFT_VERSION'] = '5.0'
    s['IPHONEOS_DEPLOYMENT_TARGET'] = deployment
    s['TARGETED_DEVICE_FAMILY'] = '1'
    s['CODE_SIGN_STYLE'] = 'Automatic'
    team = app.build_configurations.find { |c| c.name == config.name }&.build_settings&.dig('DEVELOPMENT_TEAM')
    s['DEVELOPMENT_TEAM'] = team || ''
  end
  attrs = project.root_object.attributes['TargetAttributes'] ||= {}
  attrs[target.uuid] = { 'CreatedOnToolsVersion' => '27.1', 'TestTargetID' => app.uuid }
  added << target
end
project.save

scheme_path = Xcodeproj::XCScheme.shared_data_dir(project_path)
scheme_file = File.join(scheme_path, "#{app_name}.xcscheme")
scheme = File.exist?(scheme_file) ? Xcodeproj::XCScheme.new(scheme_file) : Xcodeproj::XCScheme.new
scheme.add_build_target(app) unless File.exist?(scheme_file)
existing = scheme.test_action.testables.map { |t| t.buildable_references.first&.target_name }.compact
project.native_targets.select { |t| %w[DuoUITests DuoPerfTests].include?(t.name) }.each do |t|
  next if existing.include?(t.name)
  scheme.test_action.add_testable(Xcodeproj::XCScheme::TestAction::TestableReference.new(t))
end
scheme.test_action.build_configuration = 'Release'
scheme.save_as(project_path, app_name, true)
puts "added: #{added.map(&:name).join(', ')}; deployment target #{deployment}; scheme #{app_name} tests in Release"
